/* ===== js/script.js ===== */
/* Shared UI, storage and catalog helpers used by every page. */
const Config = window.THREADLY_CONFIG;
const Products = window.THREADLY_PRODUCTS;
const Store = {
  read(key) { try { return JSON.parse(localStorage.getItem(key)) || []; } catch { return []; } },
  write(key, value) { localStorage.setItem(key, JSON.stringify(value)); updateCounts(); },
  getCart() { return this.read("threadly_cart"); },
  saveCart(items) { this.write("threadly_cart", items); },
  addToCart(productId, size, quantity = 1) {
    const cart = this.getCart(); const found = cart.find(item => item.id === productId && item.size === size);
    if (found) found.quantity += quantity; else cart.push({ id: productId, size, quantity });
    this.saveCart(cart); toast("Added to cart.");
  },
  removeFromCart(productId, size) { this.saveCart(this.getCart().filter(item => !(item.id === productId && item.size === size))); },
  updateQuantity(productId, size, quantity) { if (quantity < 1) return this.removeFromCart(productId, size); this.saveCart(this.getCart().map(item => item.id === productId && item.size === size ? { ...item, quantity } : item)); },
  getWishlist() { return this.read("threadly_wishlist"); },
  saveWishlist(ids) { this.write("threadly_wishlist", ids); },
  toggleWishlist(id) { const list = this.getWishlist(); const active = list.includes(id); this.saveWishlist(active ? list.filter(item => item !== id) : [...list, id]); toast(active ? "Removed from wishlist." : "Added to wishlist."); refreshWishlistButtons(); return !active; },
  removeFromWishlist(id) { this.saveWishlist(this.getWishlist().filter(item => item !== id)); }
};
window.ThreadlyStore = Store;
function money(value) { return `${Config.currency}${value.toLocaleString(Config.locale)}`; }
function productById(id) { return Products.find(product => product.id === Number(id)); }
function icon(name) { const icons = { search: '<svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/></svg>', heart: '<svg viewBox="0 0 24 24"><path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8l1.1 1.1L12 21l7.7-7.5a5.5 5.5 0 0 0 1.1-8.9Z"/></svg>', bag: '<svg viewBox="0 0 24 24"><path d="M6 8h12l1 13H5L6 8Z"/><path d="M9 9V6a3 3 0 0 1 6 0v3"/></svg>', menu: '<svg viewBox="0 0 24 24"><path d="M3 7h18M3 17h18"/></svg>', close: '<svg viewBox="0 0 24 24"><path d="m5 5 14 14M19 5 5 19"/></svg>', arrow: '<svg viewBox="0 0 24 24"><path d="M5 12h14M14 7l5 5-5 5"/></svg>' }; return icons[name]; }
function pageLink(page = "index.html") { return page; }
function renderShell() {
  document.querySelectorAll("[data-brand]").forEach(el => el.textContent = Config.brandName);
  document.querySelectorAll("[data-tagline]").forEach(el => el.textContent = Config.tagline);
  const header = document.querySelector("[data-site-header]");
  if (header) header.innerHTML = `<a class="skip-link" href="#main">Skip to content</a><div class="announcement">Complimentary shipping across India on orders over ₹1,499</div><nav class="nav shell" aria-label="Main navigation"><button class="icon-button mobile-only" data-menu-open aria-label="Open menu">${icon("menu")}</button><a class="wordmark" href="${pageLink()}">${Config.brandName}</a><div class="nav-links"><a href="products.html">Shop</a><a href="products.html?sort=newest">New Arrivals</a><a href="products.html?category=T-Shirts">T-Shirts</a><a href="products.html?category=Hoodies">Hoodies</a><a href="products.html?category=Shirts">Shirts</a><a href="products.html?category=Bottomwear">Bottomwear</a></div><div class="nav-actions"><button class="nav-action" data-search-open aria-label="Search">${icon("search")}<span class="desktop-only">Search</span></button><a class="nav-action" href="wishlist.html" aria-label="Wishlist">${icon("heart")}<span class="count wishlist-count">0</span></a><a class="nav-action" href="cart.html" aria-label="Cart">${icon("bag")}<span class="count cart-count">0</span></a></div></nav><div class="mobile-menu" data-mobile-menu aria-hidden="true"><div class="mobile-menu-head"><span class="wordmark">${Config.brandName}</span><button class="icon-button" data-menu-close aria-label="Close menu">${icon("close")}</button></div><div class="mobile-menu-links"><a href="products.html">Shop All</a><a href="products.html?sort=newest">New Arrivals</a>${["T-Shirts", "Hoodies", "Shirts", "Bottomwear", "Accessories"].map(c => `<a href="products.html?category=${encodeURIComponent(c)}">${c}</a>`).join("")}</div></div><div class="search-panel" data-search-panel aria-hidden="true"><div class="search-inner shell"><form action="products.html"><label class="eyebrow" for="global-search">SEARCH THE COLLECTION</label><div class="search-line">${icon("search")}<input id="global-search" name="search" type="search" autocomplete="off" placeholder="T-shirt, black, linen…"><button class="icon-button" type="button" data-search-close aria-label="Close search">${icon("close")}</button></div></form></div></div>`;
  const footer = document.querySelector("[data-site-footer]");
  if (footer) footer.innerHTML = `<div class="footer shell"><div class="footer-brand"><a class="wordmark wordmark-large" href="index.html">${Config.brandName}</a><p>${Config.tagline}</p></div><div><h2>SHOP</h2><a href="products.html?category=T-Shirts">T-Shirts</a><a href="products.html?category=Hoodies">Hoodies</a><a href="products.html?category=Shirts">Shirts</a><a href="products.html?category=Bottomwear">Bottomwear</a></div><div><h2>HELP</h2><a href="#">Contact</a><a href="#">Shipping</a><a href="#">Returns</a><a href="product.html?id=1#size-guide">Size Guide</a></div><div><h2>SOCIAL</h2>${Object.keys(Config.social).map(name => `<a href="${Config.social[name]}">${name}</a>`).join("")}</div><div class="newsletter"><h2>NEWSLETTER</h2><p>Join the ${Config.brandName} list.</p><form data-newsletter><label class="sr-only" for="newsletter-email">Email address</label><div><input id="newsletter-email" type="email" placeholder="Your email address" required><button type="submit">Subscribe</button></div></form></div></div><div class="footer-bottom shell"><span>© 2026 ${Config.brandName}</span><span>Made for everyday expression.</span></div>`;
  bindShell(); updateCounts();
}
function bindShell() {
  const menu = document.querySelector("[data-mobile-menu]"), search = document.querySelector("[data-search-panel]");
  document.querySelector("[data-menu-open]")?.addEventListener("click", () => setPanel(menu, true));
  document.querySelector("[data-menu-close]")?.addEventListener("click", () => setPanel(menu, false));
  document.querySelector("[data-search-open]")?.addEventListener("click", () => { setPanel(search, true); setTimeout(() => document.querySelector("#global-search")?.focus(), 100) });
  document.querySelector("[data-search-close]")?.addEventListener("click", () => setPanel(search, false));
  document.addEventListener("keydown", e => { if (e.key === "Escape") { setPanel(menu, false); setPanel(search, false) } });
  document.querySelector("[data-newsletter]")?.addEventListener("submit", e => { e.preventDefault(); e.currentTarget.reset(); toast("You’re on the list.") });
  window.addEventListener("scroll", () => document.querySelector("[data-site-header]")?.classList.toggle("is-scrolled", scrollY > 20), { passive: true });
}
function setPanel(panel, open) { if (!panel) return; panel.classList.toggle("is-open", open); panel.setAttribute("aria-hidden", String(!open)); document.body.classList.toggle("no-scroll", open); }
function updateCounts() { const cart = Store.getCart().reduce((sum, item) => sum + item.quantity, 0); document.querySelectorAll(".cart-count").forEach(el => el.textContent = cart); document.querySelectorAll(".wishlist-count").forEach(el => el.textContent = Store.getWishlist().length); }
function toast(message) { let region = document.querySelector(".toast-region"); if (!region) { region = document.createElement("div"); region.className = "toast-region"; region.setAttribute("aria-live", "polite"); document.body.append(region) } const item = document.createElement("div"); item.className = "toast"; item.textContent = message; region.append(item); setTimeout(() => item.remove(), 2800); }
function productCard(product) { const active = Store.getWishlist().includes(product.id); return `<article class="product-card fade-in"><div class="product-media"><a href="product.html?id=${product.id}" aria-label="View ${product.name}"><img src="${product.image}" alt="${product.name} in ${product.color}" width="1024" height="1200" loading="lazy"></a>${product.badge ? `<span class="badge">${product.badge}</span>` : ""}<button class="heart ${active ? "is-active" : ""}" data-wishlist-id="${product.id}" aria-label="${active ? "Remove from" : "Add to"} wishlist">${icon("heart")}</button><button class="quick-add" data-quick-add="${product.id}">Quick add</button></div><div class="product-info"><div><p class="product-category">${product.category}</p><h3><a href="product.html?id=${product.id}">${product.name}</a></h3></div><p class="product-price">${money(product.price)}</p></div><p class="product-meta"><span>${product.color}</span><span>★ ${product.rating}</span></p></article>`; }
function bindProductCards(root = document) { root.querySelectorAll("[data-wishlist-id]").forEach(btn => btn.addEventListener("click", () => { Store.toggleWishlist(Number(btn.dataset.wishlistId)); refreshWishlistButtons() })); root.querySelectorAll("[data-quick-add]").forEach(btn => btn.addEventListener("click", () => { const p = productById(btn.dataset.quickAdd); if (p) Store.addToCart(p.id, p.sizes[0]) })); }
function refreshWishlistButtons() { document.querySelectorAll("[data-wishlist-id]").forEach(btn => { const active = Store.getWishlist().includes(Number(btn.dataset.wishlistId)); btn.classList.toggle("is-active", active); btn.setAttribute("aria-label", `${active ? "Remove from" : "Add to"} wishlist`) }); updateCounts(); }
function initReveal() { const observer = new IntersectionObserver(entries => entries.forEach(entry => { if (entry.isIntersecting) { entry.target.classList.add("visible"); observer.unobserve(entry.target) } }), { threshold: .08 }); document.querySelectorAll(".fade-in").forEach(el => observer.observe(el)); }
document.addEventListener("DOMContentLoaded", () => { renderShell(); bindProductCards(); initReveal(); });
window.Threadly = { Config, Products, Store, money, productById, productCard, bindProductCards, initReveal, toast, icon };


/* ===== js/shop.js ===== */
document.addEventListener("DOMContentLoaded", () => {
  const params = new URLSearchParams(location.search);
  const highestPrice = Math.ceil(Math.max(...Threadly.Products.map((product) => product.price)) / 100) * 100;
  const state = { search: params.get("search") || "", category: params.get("category") || "All", size: "All", color: "All", max: highestPrice, sort: params.get("sort") || "featured" };
  const categories = ["All", ...new Set(Threadly.Products.map((product) => product.category))];
  const sizes = ["All", ...new Set(Threadly.Products.flatMap((product) => product.sizes))];
  const colors = ["All", ...new Set(Threadly.Products.flatMap((product) => product.colors))];
  const makeRadios = (items, key) => items.map((item) => `<label><input type="radio" name="${key}" value="${item}" ${state[key] === item ? "checked" : ""}> ${item}</label>`).join("");
  document.querySelector("[data-category-filters]").innerHTML = makeRadios(categories, "category");
  document.querySelector("[data-size-filters]").innerHTML = makeRadios(sizes, "size");
  document.querySelector("[data-color-filters]").innerHTML = makeRadios(colors, "color");
  const priceInput = document.querySelector("[data-price]");
  priceInput.max = highestPrice; priceInput.value = highestPrice;
  document.querySelector("[data-price-value]").textContent = Threadly.money(highestPrice);
  const search = document.querySelector("#shop-search"); search.value = state.search;
  document.querySelector("[data-sort]").value = state.sort;
  function render() {
    let list = Threadly.Products.filter((product) => (state.category === "All" || product.category === state.category) && (state.size === "All" || product.sizes.includes(state.size)) && (state.color === "All" || product.colors.includes(state.color)) && product.price <= state.max);
    if (state.search) { const query = state.search.toLowerCase(); list = list.filter((product) => `${product.name} ${product.category} ${product.colors.join(" ")} ${product.description} ${product.keywords}`.toLowerCase().includes(query)); }
    const sorters = { low: (a, b) => a.price - b.price, high: (a, b) => b.price - a.price, rating: (a, b) => b.rating - a.rating, newest: (a, b) => b.created - a.created, featured: (a, b) => b.rating - a.rating };
    list.sort(sorters[state.sort]);
    document.querySelector("[data-result-count]").textContent = list.length;
    const grid = document.querySelector("[data-shop-grid]");
    grid.innerHTML = list.length ? list.map(Threadly.productCard).join("") : '<div class="empty-state"><h2>No pieces found.</h2><p>Try a different search or clear your filters.</p><button class="button button-outline" data-empty-clear>Clear search</button></div>';
    Threadly.bindProductCards(grid); Threadly.initReveal(); document.querySelector("[data-empty-clear]")?.addEventListener("click", clear);
  }
  document.querySelectorAll(".filters input[type=radio]").forEach((input) => input.addEventListener("change", () => { state[input.name] = input.value; render(); }));
  search.addEventListener("input", () => { state.search = search.value.trim(); render(); });
  document.querySelector("[data-sort]").addEventListener("change", (event) => { state.sort = event.target.value; render(); });
  priceInput.addEventListener("input", (event) => { state.max = Number(event.target.value); document.querySelector("[data-price-value]").textContent = Threadly.money(state.max); render(); });
  function clear() { state.search = ""; state.category = "All"; state.size = "All"; state.color = "All"; state.max = highestPrice; search.value = ""; priceInput.value = highestPrice; document.querySelector("[data-price-value]").textContent = Threadly.money(highestPrice); document.querySelectorAll(".filters input").forEach((input) => { input.checked = input.value === "All"; }); render(); }
  document.querySelector("[data-clear-filters]").addEventListener("click", clear);
  document.querySelector("[data-filter-toggle]").addEventListener("click", (event) => { const open = document.querySelector(".filters").classList.toggle("is-open"); event.currentTarget.setAttribute("aria-expanded", open); });
  render();
});

/* ===== js/product.js ===== */
document.addEventListener("DOMContentLoaded", () => {
  const product = Threadly.productById(new URLSearchParams(location.search).get("id") || 1);
  const root = document.querySelector("[data-product-page]");
  if (!product) {
    root.innerHTML = '<div class="empty-collection"><h1>Piece not found.</h1><a class="button" href="products.html">Return to shop</a></div>';
    return;
  }

  document.title = `${product.name} — ${Threadly.Config.brandName}`;
  let size = product.sizes[0];
  let color = product.colors[0];
  let quantity = 1;
  const gallery = [product.image, product.image, product.image];

  root.innerHTML = `
    <nav class="breadcrumbs" aria-label="Breadcrumb"><a href="index.html">Home</a> / <a href="products.html?category=${encodeURIComponent(product.category)}">${product.category}</a> / ${product.name}</nav>
    <div class="product-layout">
      <div class="product-gallery">${gallery.map((image, index) => `<figure><img src="${image}" alt="${index ? `${product.name} styling detail` : `${product.name} in ${color}`}" width="768" height="960"></figure>`).join("")}</div>
      <section class="product-panel">
        <p class="eyebrow">${product.category}</p><h1>${product.name}</h1>
        <div class="product-rating"><span>★ ${product.rating}</span><span>Based on verified wear</span></div>
        <p class="detail-price">${Threadly.money(product.price)}</p><p class="detail-description">${product.description}</p>
        <div class="option-head"><span>SELECT COLOUR — <strong data-colour-name>${color}</strong></span><span>${product.colors.length} options</span></div>
        <div class="colour-options">${product.colors.map((item, index) => `<button class="colour-option ${index === 0 ? "is-active" : ""}" data-colour="${item}" aria-label="Choose ${item}" aria-pressed="${index === 0}"><span class="swatch swatch-${Threadly.colorSlug(item)}"></span>${item}</button>`).join("")}</div>
        <div class="option-head"><span>SELECT SIZE</span><a href="#size-guide">Size guide</a></div>
        <div class="size-options">${product.sizes.map((item, index) => `<button class="size-option ${index === 0 ? "is-active" : ""}" data-size="${item}" aria-pressed="${index === 0}">${item}</button>`).join("")}</div>
        <div class="quantity-row"><span class="eyebrow">QUANTITY</span><div class="quantity"><button data-minus aria-label="Decrease quantity">−</button><span data-quantity>1</span><button data-plus aria-label="Increase quantity">+</button></div></div>
        <div class="product-actions"><button class="button" data-add-cart>Add to cart</button><button class="button button-outline heart-large" data-wish aria-label="Add to wishlist">${Threadly.icon("heart")}</button></div>
        <p class="availability">In stock — ${product.stock} available</p>
        <div class="detail-accordions"><details open><summary>PRODUCT DETAILS</summary><p>${product.description}</p></details><details><summary>MATERIAL</summary><p>${product.material}</p></details><details><summary>CARE INSTRUCTIONS</summary><p>${product.care}</p></details><details id="size-guide"><summary>SIZE GUIDE</summary><p>Choose your usual size for the intended relaxed fit. If between sizes, select the smaller size for a closer silhouette.</p></details></div>
      </section>
    </div>`;

  root.querySelectorAll("[data-size]").forEach((button) => button.addEventListener("click", () => {
    size = button.dataset.size;
    root.querySelectorAll("[data-size]").forEach((item) => { item.classList.toggle("is-active", item === button); item.setAttribute("aria-pressed", item === button); });
  }));
  root.querySelectorAll("[data-colour]").forEach((button) => button.addEventListener("click", () => {
    color = button.dataset.colour;
    root.querySelector("[data-colour-name]").textContent = color;
    root.querySelectorAll("[data-colour]").forEach((item) => { item.classList.toggle("is-active", item === button); item.setAttribute("aria-pressed", item === button); });
  }));
  const quantityLabel = root.querySelector("[data-quantity]");
  root.querySelector("[data-minus]").addEventListener("click", () => { quantity = Math.max(1, quantity - 1); quantityLabel.textContent = quantity; });
  root.querySelector("[data-plus]").addEventListener("click", () => { quantity = Math.min(product.stock, quantity + 1); quantityLabel.textContent = quantity; });
  root.querySelector("[data-add-cart]").addEventListener("click", () => Threadly.Store.addToCart(product.id, size, quantity, color));
  const wishlistButton = root.querySelector("[data-wish]");
  const syncWishlist = () => wishlistButton.classList.toggle("is-active", Threadly.Store.getWishlist().includes(product.id));
  wishlistButton.addEventListener("click", () => { Threadly.Store.toggleWishlist(product.id); syncWishlist(); });
  syncWishlist();
});

/* ===== js/cart.js ===== */
document.addEventListener("DOMContentLoaded", () => {
  const root = document.querySelector("[data-cart-page]");
  function render() {
    const items = Threadly.Store.getCart().map((item) => {
      const product = Threadly.productById(item.id);
      return product ? { ...item, color: item.color || product.colors[0], product } : null;
    }).filter(Boolean);
    if (!items.length) {
      root.innerHTML = '<div class="empty-collection"><h2>Your bag is empty.</h2><p>Discover considered essentials for everyday expression.</p><a class="button" href="products.html">Continue shopping</a></div>';
      return;
    }
    const subtotal = items.reduce((sum, item) => sum + item.product.price * item.quantity, 0);
    const shipping = subtotal >= 1499 ? 0 : 99;
    root.innerHTML = `<div class="cart-layout"><section class="cart-list" aria-label="Cart items">${items.map((item, index) => `<article class="cart-item"><a href="product.html?id=${item.id}"><img src="${item.product.image}" alt="${item.product.name} in ${item.color}" width="768" height="960"></a><div><h2><a href="product.html?id=${item.id}">${item.product.name}</a></h2><p>${item.color} / ${item.size}</p><div class="cart-item-controls"><div class="quantity"><button data-dec="${index}" aria-label="Decrease ${item.product.name} quantity">−</button><span>${item.quantity}</span><button data-inc="${index}" aria-label="Increase ${item.product.name} quantity">+</button></div><button class="remove-link" data-remove="${index}">Remove</button></div></div><div class="cart-item-price">${Threadly.money(item.product.price * item.quantity)}</div></article>`).join("")}</section><aside class="summary"><h2>Order summary</h2><div class="summary-line"><span>Subtotal</span><span>${Threadly.money(subtotal)}</span></div><div class="summary-line"><span>Shipping</span><span>${shipping ? Threadly.money(shipping) : "FREE"}</span></div><div class="summary-line summary-total"><span>Total</span><span>${Threadly.money(subtotal + shipping)}</span></div><button class="button" data-checkout>Proceed to checkout</button><p class="summary-note">Secure checkout is shown for demonstration.</p><a class="text-link" href="products.html">Continue shopping</a></aside></div>`;
    root.querySelectorAll("[data-dec]").forEach((button) => button.addEventListener("click", () => change(items[Number(button.dataset.dec)], -1)));
    root.querySelectorAll("[data-inc]").forEach((button) => button.addEventListener("click", () => change(items[Number(button.dataset.inc)], 1)));
    root.querySelectorAll("[data-remove]").forEach((button) => button.addEventListener("click", () => { const item = items[Number(button.dataset.remove)]; Threadly.Store.removeFromCart(item.id, item.size, item.color); render(); }));
    root.querySelector("[data-checkout]").addEventListener("click", () => Threadly.toast("Checkout is a demo in this frontend project."));
  }
  function change(item, delta) { Threadly.Store.updateQuantity(item.id, item.size, item.quantity + delta, item.color); render(); }
  render();
});

/* ===== js/wishlist.js ===== */
document.addEventListener("DOMContentLoaded", () => { const root = document.querySelector("[data-wishlist-grid]"); function render() { const list = Threadly.Store.getWishlist().map(Threadly.productById).filter(Boolean); root.innerHTML = list.length ? list.map(Threadly.productCard).join("") : `<div class="empty-collection"><h2>Nothing saved yet.</h2><p>Keep a quiet edit of the pieces you want to return to.</p><a class="button" href="products.html">Explore the collection</a></div>`; Threadly.bindProductCards(root); root.querySelectorAll("[data-wishlist-id]").forEach(btn => btn.addEventListener("click", () => setTimeout(render, 0))); Threadly.initReveal() } render() });

/* ===== Homepage initialization ===== */
document.addEventListener("DOMContentLoaded", () => {
  const categoryRoot = document.querySelector("[data-categories]");
  if (!categoryRoot) return;
  const cats = ["T-Shirts", "Hoodies", "Shirts", "Bottomwear", "Accessories"];
  categoryRoot.innerHTML = cats.map(c => `<a class="category-card fade-in" href="products.html?category=${encodeURIComponent(c)}"><img src="${Threadly.Config.images[c]}" alt="Explore ${c}" width="1024" height="1200" loading="lazy"><span class="category-label"><h3>${c}</h3>${Threadly.icon("arrow")}</span></a>`).join("");
  const featured = document.querySelector("[data-featured]");
  if (featured) featured.innerHTML = Threadly.Products.slice(0, 4).map(Threadly.productCard).join("");
  document.querySelectorAll("[data-arrow]").forEach(el => el.innerHTML = Threadly.icon("arrow"));
  Threadly.bindProductCards(document);
  Threadly.initReveal();
});
